(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10 + Math.sin((x+y)*0.01+t*0.15)*8;
  const wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10 + Math.cos((x-y)*0.012-t*0.18)*8;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.7],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65)*50, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+1)*40, 0.13, 1.8, 1.05]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,am] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w = Math.sin(d*f-t*sp)*am;
    aS += w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*am;
    cS += Math.sin(d*f*1.4-t*sp*1.3+0.7)*am*0.5;
  }
  const n=8, act=aS/n, inh=iS/n, crs=cS/n;
  const bg1 = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2 = Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3 = Math.sin(sx*0.08+t*0.5)*Math.sin(sy*0.06-t*0.7)*0.3;
  const bg = bg1+bg2+bg3;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.05-ang*3-t*1.5);
  const sp2 = Math.sin(dist*0.04+ang*4-t*1.2);
  const sp3 = Math.sin(dist*0.08-ang*2+t*0.9)*0.5;
  const spiral = (sp1+sp2)*0.35+sp3;
  const rd1 = Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const rd2 = Math.tanh((crs-inh*0.5+act*0.4-bg*0.2)*1.8);
  const rdMix = rd1*0.7+rd2*0.3;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const voronoi = (() => {
    let md = 99, sd = 99;
    for (let i = 0; i < 5; i++) {
      const vx = (Math.sin(i*7.31+t*0.4)*0.5+0.5)*480;
      const vy = (Math.cos(i*5.17+t*0.3)*0.5+0.5)*240;
      const d = Math.sqrt((sx-vx)**2+(sy-vy)**2);
      if (d < md) { sd = md; md = d; } else if (d < sd) sd = d;
    }
    return Math.tanh((sd-md)*0.15)*0.2;
  })();
  const edge = Math.abs(rdMix);
  const glow = Math.exp(-edge*3)*0.3;
  const blend = rdMix*0.6+cell*0.2+voronoi*0.1+glow*0.1;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[10,42,88],[15,85,115],[18,130,130],
    [80,165,120],[180,185,80],[210,155,65],[200,100,70],
    [160,60,80],[100,30,65],[45,15,55],[5,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.82+Math.sin(rdMix*Math.PI)*0.18;
  const eBoost = edge>0.65?1.0+glow*1.5:1.0;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*eBoost)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*eBoost)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*eBoost)|0
  ];
}
